with unpivoted as (select * from (select id, category, price, cost from products) src unpivot include nulls (value for kpi in (price, cost))) select case when value >= 89 then 'LARGE' else 'SMALL' end as value_tier, sum(case when kpi = 'price' then value else 0 end) as price_value, percentile_approx(value, array(0.25, 0.5, 0.75)) as value_quartiles from unpivoted group by case when value >= 89 then 'LARGE' else 'SMALL' end having price_value >= 0 order by price_value desc
